"""Vendored benchmark primitives; generated by vendor_benchmark.py."""

from __future__ import annotations
import json, math, re, shutil
from pathlib import Path
from typing import Any

TOOL_SCHEMAS = json.loads(Path(__file__).with_name('tool-schemas.json').read_text())

def _validate_arguments(value: Any, schema: dict, location: str = "arguments") -> str | None:
    """Validate the JSON Schema subset used by this fixed tool registry.

    Keep the API harness dependency-free. This is not a general JSON Schema
    engine: the registry uses types, properties, required, enum, items, bounds,
    and additionalProperties only.
    """
    if not isinstance(value, (dict, list, str, int, float, bool, type(None))):
        return f"{location} must contain JSON values only"
    if isinstance(value, float) and not math.isfinite(value):
        return f"{location} must contain finite JSON numbers"
    checks = {
        "object": lambda x: isinstance(x, dict),
        "array": lambda x: isinstance(x, list),
        "string": lambda x: isinstance(x, str),
        "integer": lambda x: (isinstance(x, (int, float)) and not isinstance(x, bool)
                              and (isinstance(x, int) or x.is_integer())),
        "boolean": lambda x: isinstance(x, bool),
        "null": lambda x: x is None,
    }
    types = schema.get("type", [])
    types = types if isinstance(types, list) else [types]
    if types and not any(checks[t](value) for t in types):
        return f"{location} must be {' or '.join(types)}"
    if "enum" in schema and value not in schema["enum"]:
        return f"{location} must be one of {schema['enum']!r}"
    if isinstance(value, dict):
        properties = schema.get("properties", {})
        missing = [key for key in schema.get("required", []) if key not in value]
        if missing:
            return f"{location} is missing required field(s): {', '.join(missing)}"
        if schema.get("additionalProperties") is False:
            unknown = [str(key) for key in value if key not in properties]
            if unknown:
                return f"{location} has unknown field(s): {', '.join(unknown)}"
        for key, child in value.items():
            if not isinstance(key, str):
                return f"{location} must use string keys"
            error = _validate_arguments(child, properties.get(key, {}), f"{location}.{key}")
            if error:
                return error
    if isinstance(value, list):
        if len(value) > schema.get("maxItems", len(value)):
            return f"{location} exceeds maxItems {schema['maxItems']}"
        for index, child in enumerate(value):
            error = _validate_arguments(child, schema.get("items", {}), f"{location}[{index}]")
            if error:
                return error
    if isinstance(value, str) and len(value) < schema.get("minLength", 0):
        return f"{location} must not be empty"
    for bound, compare in (("minimum", lambda a, b: a < b), ("maximum", lambda a, b: a > b)):
        if bound in schema and compare(value, schema[bound]):
            return f"{location} violates {bound} {schema[bound]}"
    return None

def validate_tool_call(name: str, arguments: Any, allowed_tools: set[str]) -> dict | None:
    """Reject unavailable names and invalid arguments before any dispatch."""
    schema = next((tool for tool in TOOL_SCHEMAS if tool["name"] == name), None)
    if not isinstance(name, str) or name not in allowed_tools or schema is None:
        return {"is_final_answer": False, "error_type": "disallowed_tool",
                "error": f"Tool {name!r} is unavailable. Allowed tools: {', '.join(sorted(allowed_tools))}."}
    try:
        error = _validate_arguments(arguments, schema["input_schema"])
    except RecursionError:
        error = "arguments are nested too deeply"
    if error is None and name == "final_answer":
        if "encryption_components" in arguments and "encryption_details" in arguments:
            error = "use encryption_components or legacy encryption_details, not both"
        ids = [re.sub(r"[^a-z0-9]+", "_", row["id"].lower()).strip("_")
               for row in arguments.get("encryption_components", [])]
        if any(not ident for ident in ids) or len(ids) != len(set(ids)):
            error = "encryption component IDs must be meaningful and unique"
    if error:
        return {"is_final_answer": False, "error_type": "invalid_arguments",
                "error": f"Invalid {name} call: {error}. Follow the supplied tool schema."}
    return None

ENTROPY_SCRIPT = r'''
import math, struct, sys, os

def entropy(data, window=256):
    results = []
    for i in range(0, len(data), window):
        chunk = data[i:i+window]
        if len(chunk) < 16:
            break
        freq = [0]*256
        for b in chunk:
            freq[b] += 1
        n = len(chunk)
        ent = 0.0
        for f in freq:
            if f > 0:
                p = f / n
                ent -= p * math.log2(p)
        results.append((i, len(chunk), round(ent, 4)))
    return results

path = sys.argv[1]
section = sys.argv[2] if len(sys.argv) > 2 and sys.argv[2] != "" else None
window = int(sys.argv[3]) if len(sys.argv) > 3 else 256

with open(path, "rb") as f:
    data = f.read()

if section:
    if data[:2] == b"MZ":
        # PE binary: locate the section via pefile
        try:
            import pefile
        except ImportError:
            print("Error: pefile not available in sandbox", file=sys.stderr)
            sys.exit(1)
        pe = pefile.PE(path)
        found = False
        for sec in pe.sections:
            sname = sec.Name.rstrip(b"\x00").decode("ascii", errors="replace")
            if sname == section:
                data = sec.get_data()
                found = True
                break
        if not found:
            print(f"Section {section!r} not found", file=sys.stderr)
            sys.exit(1)
    elif data[:4] == b"\x7fELF":
        # Parse ELF section headers to find the section
        is_64 = data[4] == 2
        if is_64:
            e_shoff = struct.unpack_from("<Q", data, 40)[0]
            e_shentsize = struct.unpack_from("<H", data, 58)[0]
            e_shnum = struct.unpack_from("<H", data, 60)[0]
            e_shstrndx = struct.unpack_from("<H", data, 62)[0]
            # Get section name string table
            str_sh_off = e_shoff + e_shstrndx * e_shentsize
            str_sh_offset = struct.unpack_from("<Q", data, str_sh_off + 24)[0]
            str_sh_size = struct.unpack_from("<Q", data, str_sh_off + 32)[0]
            strtab = data[str_sh_offset:str_sh_offset+str_sh_size]
            found = False
            for i in range(e_shnum):
                off = e_shoff + i * e_shentsize
                sh_name_idx = struct.unpack_from("<I", data, off)[0]
                name = strtab[sh_name_idx:].split(b"\x00")[0].decode("ascii", errors="replace")
                if name == section:
                    sh_offset = struct.unpack_from("<Q", data, off + 24)[0]
                    sh_size = struct.unpack_from("<Q", data, off + 32)[0]
                    data = data[sh_offset:sh_offset+sh_size]
                    found = True
                    break
            if not found:
                print(f"Section {section!r} not found", file=sys.stderr)
                sys.exit(1)
        else:
            print("Only ELF64 supported for section targeting", file=sys.stderr)
            sys.exit(1)
    else:
        print("Error: unknown binary format (not ELF or PE)", file=sys.stderr)
        sys.exit(1)

results = entropy(data, window)
total_ent = 0.0
if data:
    freq = [0]*256
    for b in data:
        freq[b] += 1
    n = len(data)
    for f in freq:
        if f > 0:
            p = f / n
            total_ent -= p * math.log2(p)

print(f"Total size: {len(data)} bytes")
print(f"Overall entropy: {total_ent:.4f} bits/byte")
print(f"Window size: {window} bytes")
print(f"Windows analyzed: {len(results)}")
print()
if results:
    ents = [r[2] for r in results]
    print(f"Min window entropy: {min(ents):.4f}")
    print(f"Max window entropy: {max(ents):.4f}")
    print(f"Avg window entropy: {sum(ents)/len(ents):.4f}")
    print()
    print("Offset      Size  Entropy")
    print("-" * 35)
    for offset, size, ent in results:
        bar = "#" * int(ent * 4)
        print(f"0x{offset:08x}  {size:4d}  {ent:.4f}  {bar}")
'''

PE_INFO_SCRIPT = r'''
import sys

try:
    import pefile
except ImportError:
    print("Error: pefile not available in sandbox", file=sys.stderr)
    sys.exit(1)

path = sys.argv[1]
try:
    pe = pefile.PE(path)
except Exception as e:
    print(f"Error: cannot parse as PE: {e}", file=sys.stderr)
    sys.exit(1)

MACHINES = {0x8664: "x86-64", 0x14C: "i386", 0xAA64: "arm64", 0x1C0: "arm"}
mach = MACHINES.get(pe.FILE_HEADER.Machine, hex(pe.FILE_HEADER.Machine))
pe_plus = pe.PE_TYPE == pefile.OPTIONAL_HEADER_MAGIC_PE_PLUS
print(f"Format:      {'PE32+' if pe_plus else 'PE32'} ({mach})")
print(f"Entry point: 0x{pe.OPTIONAL_HEADER.AddressOfEntryPoint:08x}")
print(f"Image base:  0x{pe.OPTIONAL_HEADER.ImageBase:x}")
print(f"Subsystem:   {pe.OPTIONAL_HEADER.Subsystem}")
print(f"Sections:    {pe.FILE_HEADER.NumberOfSections}")
print(f"Timestamp:   {pe.FILE_HEADER.TimeDateStamp}")

print("\nSECTIONS:")
for s in pe.sections:
    name = s.Name.rstrip(b"\x00").decode("ascii", errors="replace")
    print(
        f"  {name:10s} vsize=0x{s.Misc_VirtualSize:07x} "
        f"raw=0x{s.SizeOfRawData:07x} entropy={s.get_entropy():5.2f} "
        f"chars=0x{s.Characteristics:08x}"
    )

print("\nIMPORTS:")
if hasattr(pe, "DIRECTORY_ENTRY_IMPORT"):
    for entry in pe.DIRECTORY_ENTRY_IMPORT:
        dll = entry.dll.decode("ascii", errors="replace")
        funcs = []
        for imp in entry.imports:
            funcs.append(imp.name.decode("ascii", errors="replace") if imp.name else f"ord{imp.ordinal}")
        print(f"  {dll} ({len(funcs)} functions)")
        for f in funcs:
            print(f"    {f}")
else:
    print("  NONE — empty IAT. Manual API resolution likely")
    print("  (PEB walking, export-table parsing, or direct syscalls).")

print("\nEXPORTS:")
if hasattr(pe, "DIRECTORY_ENTRY_EXPORT"):
    for sym in pe.DIRECTORY_ENTRY_EXPORT.symbols:
        name = sym.name.decode("ascii", errors="replace") if sym.name else f"ord{sym.ordinal}"
        print(f"  {name}")
else:
    print("  none")

print("\nTLS CALLBACKS:")
tls = getattr(pe, "DIRECTORY_ENTRY_TLS", None)
if tls and getattr(tls.struct, "AddressOfCallBacks", 0):
    print(f"  present (callback array VA 0x{tls.struct.AddressOfCallBacks:x})")
else:
    print("  none")

print("\nRESOURCES:")
if hasattr(pe, "DIRECTORY_ENTRY_RESOURCE"):
    try:
        kinds = set()
        for rtype in pe.DIRECTORY_ENTRY_RESOURCE.entries:
            kinds.add(str(rtype.id))
        print(f"  present (resource type ids: {', '.join(sorted(kinds))})")
    except Exception:
        print("  present")
else:
    print("  none")
'''

def _is_pe_file(path) -> bool:
    """Sniff magic bytes: True if the file is a PE (MZ), False otherwise."""
    try:
        with open(path, "rb") as f:
            return f.read(2) == b"MZ"
    except OSError:
        return False

def _is_x86_64_elf(path) -> bool:
    """Return True for little-endian ELF files with EM_X86_64."""
    try:
        with open(path, "rb") as f:
            header = f.read(20)
        return (
            len(header) >= 20
            and header[:4] == b"\x7fELF"
            and header[5] == 1
            and int.from_bytes(header[18:20], "little") == 0x3E
        )
    except OSError:
        return False

class BenchmarkCommands:
    def _build_command(self, tool_name: str, args: dict[str, Any]) -> list[str]:
        path = args.get("path")
        if not isinstance(path, str) or not path.strip():
            raise ValueError(f"Tool {tool_name!r} requires a non-empty path")
        run_path, host_path = self._resolve_paths(path)
        if not host_path.is_file():
            raise ValueError(f"Tool {tool_name!r} requires a file, not a directory: {path!r}")
        is_pe = _is_pe_file(host_path)

        if tool_name == "file":
            return ["file", run_path]

        if tool_name == "strings":
            cmd = ["strings"]
            ml = args.get("min_length")
            if ml is not None:
                cmd += ["-n", str(int(ml))]
            enc = args.get("encoding")
            if enc:
                if enc not in ("s", "S", "b", "l", "B", "L"):
                    raise ValueError(f"Invalid strings encoding: {enc!r}")
                cmd += ["-e", enc]
            cmd.append(run_path)
            return cmd

        if tool_name == "readelf":
            if is_pe:
                raise ValueError(
                    "readelf is ELF-only; this is a PE binary. "
                    "Use pe_info for headers/sections/imports, "
                    "or objdump -p for the import table."
                )
            flags = args.get("flags", "-h")
            if flags not in ("-h", "-S", "-s", "-l", "-d", "-a"):
                raise ValueError(f"Invalid readelf flag: {flags!r}")
            return ["readelf", flags, run_path]

        if tool_name == "objdump":
            flags = args.get("flags", "-d")
            if flags not in ("-d", "-D", "-t", "-x", "-s", "-p"):
                raise ValueError(f"Invalid objdump flag: {flags!r}")
            if is_pe:
                exe = "x86_64-w64-mingw32-objdump"
            elif _is_x86_64_elf(host_path):
                exe = "x86_64-linux-gnu-objdump" if self.config.use_docker else (shutil.which("x86_64-linux-gnu-objdump") or "objdump")
            else:
                exe = "objdump"
            cmd = [exe, flags]
            section = args.get("section")
            if section:
                cmd += ["-j", str(section)]
            start, stop = args.get("start_address"), args.get("stop_address")
            if start is not None and stop is not None and stop <= start:
                raise ValueError("stop_address must be greater than start_address")
            if start is not None:
                cmd.append(f"--start-address={int(start)}")
            if stop is not None:
                cmd.append(f"--stop-address={int(stop)}")
            if args.get("function"):
                if flags != "-d":
                    raise ValueError("function requires flags=-d")
                cmd.append("--disassemble=" + args["function"])
            cmd.append(run_path)
            return cmd

        if tool_name == "nm":
            exe = "x86_64-w64-mingw32-nm" if is_pe else "nm"
            return [exe, run_path]

        if tool_name == "hexdump":
            offset = args.get("offset", 0)
            length = min(args.get("length", 256), 4096)
            return ["hexdump", "-C", "-s", str(int(offset)), "-n", str(int(length)), run_path]

        if tool_name == "xxd":
            offset = args.get("offset", 0)
            length = min(args.get("length", 256), 4096)
            return ["xxd", "-s", str(int(offset)), "-l", str(int(length)), run_path]

        if tool_name == "entropy":
            section = args.get("section", "")
            window = str(int(args.get("window_size", 256)))
            return [
                "python3", "-c", ENTROPY_SCRIPT,
                run_path, section, window,
            ]

        if tool_name == "pe_info":
            if not is_pe:
                raise ValueError(
                    "pe_info is for PE binaries; this file is not PE. "
                    "Use readelf/objdump for ELF binaries."
                )
            return ["python3", "-c", PE_INFO_SCRIPT, run_path]

        raise ValueError(f"Unknown tool: {tool_name!r}")
